 if(b.dataset.notify!==undefined){stop();P.openModal('到货通知',`<form id="notify-form"><p>商品：${esc(P.products[Number(b.dataset.notify)].pName)}</p><div class="form-row"><label for="notify-phone">演示手机号</label><input class="field" id="notify-phone" value="13800000000" pattern="1[0-9]{10}" required></div><div class="form-row"><label for="notify-code">演示验证码</label><input class="field" id="notify-code" value="123456" pattern="123456" required></div><button class="primary-button wide">订阅演示通知</button></form>${notice}`);return;}
