 if(b.dataset.asset){stop();assetView(b.dataset.asset);return;}
 if(b.dataset.loginTab){stop();login(b.dataset.loginTab);return;}
 if(b.dataset.coupon){stop();const c={welcome:{amount:100,minimum:3000,name:'新人购机礼'},member:{amount:200,minimum:6000,name:'会员专属券'},education:{amount:150,minimum:4000,name:'教育购机券'}}[b.dataset.coupon];if(!state.coupons.some(x=>x.id===b.dataset.coupon)){state.coupons.push({id:b.dataset.coupon,...c});persist();offers();}return;}
