 if(b.dataset.orderFilter){stop();orderFilter=b.dataset.orderFilter;renderOrders();return;}
 if(b.dataset.payOrder){stop();const id=b.dataset.payOrder;P.openModal('模拟支付',`<p>请选择支付方式，仅演示成功状态，不会扣款。</p><div class="payment-methods"><label><input type="radio" name="pay-method" checked>微信支付</label><label><input type="radio" name="pay-method">支付宝</label><label><input type="radio" name="pay-method">银行卡</label></div><button class="primary-button wide" data-order-state="${esc(id)}:待发货">确认模拟支付</button>`);return;}
 if(b.dataset.orderState){stop();const[id,status]=b.dataset.orderState.split(':');const o=P.orders.find(x=>x.id===id);if(o){o.status=status;P.persist();P.closeModal();go('/order/'+id);P.toast('订单状态已更新（演示）');}return;}
 if(b.dataset.logistics){stop();P.openModal('物流跟踪 · 演示','<ol class="timeline"><li><strong>订单已提交</strong><p>系统已记录演示订单。</p></li><li><strong>仓库处理中</strong><p>无真实物流单号，仅展示流程。</p></li><li><strong>配送与签收</strong><p>可在订单详情体验确认收货。</p></li></ol>');return;}
