 if(b.dataset.pin){stop();const h=P.history.find(x=>x.id===b.dataset.pin);if(h)h.pinned=!h.pinned;P.persist();renderHistoryFull($('#history-search-full').value);return;}
 if(b.dataset.historyRemove){stop();P.openModal('删除对话',`<p>删除后无法恢复，确认删除这条演示对话？</p><div class="modal-actions"><button class="primary-button" data-history-confirm="${esc(b.dataset.historyRemove)}">确认删除</button>${btn('取消','history-cancel')}</div>`);return;}
 if(b.dataset.historyConfirm){stop();const i=P.history.findIndex(x=>x.id===b.dataset.historyConfirm);if(P.conversation?.id===b.dataset.historyConfirm)P.home();if(i>=0)P.history.splice(i,1);P.persist();historyFull();return;}
 if(b.dataset.answer){stop();const[k,i]=b.dataset.answer.split(':'),el=$$('.message.assistant')[Number(i)],text=el?.querySelector('.assistant-content')?.innerText||'';if(k==='copy')await copyText(text);if(k==='share'){P.openModal('分享回答',`<textarea class="field" id="share-text" readonly rows="5">${esc(text)}</textarea><p class="fine-print">仅复制文字，不创建公开分享页面。</p>${btn('复制分享内容','copy-share','primary-button')}`);}if(k==='like'){b.textContent='已赞';b.disabled=true;}if(k==='dislike')feedback('回答反馈');if(k==='retry'){const m=P.conversation.messages.filter(x=>x.role==='assistant')[Number(i)];P.ask(m.text,P.decisionFor(m));}if(k==='speak'){if(!('speechSynthesis'in window)){P.toast('当前浏览器不支持朗读');return;}if(speechSynthesis.speaking){speechSynthesis.paused?(speechSynthesis.resume(),b.textContent='暂停'):(speechSynthesis.pause(),b.textContent='继续');}else{const utter=new SpeechSynthesisUtterance(text);utter.lang='zh-CN';utter.onend=()=>b.textContent='朗读';speechSynthesis.speak(utter);b.textContent='暂停';}}return;}
