 if(id==='checkout-form'){const items=P.cart.map(x=>({...x}));if(!items.length)return;const order={id:'DEMO-'+Date.now().toString().slice(-8),date:new Date().toLocaleString('zh-CN'),items,total:items.reduce((s,x)=>s+(x.price||P.products[x.id].price)*x.qty,0),status:'待付款',...fields};P.orders.unshift(order);P.cart.splice(0);P.persist();P.badge();P.closeModal();go('/order/'+order.id);}
 if(id==='after-sales-form'){const o=P.orders.find(x=>x.id===form.dataset.orderId);if(o){o.status='售后';o.afterSales=fields;P.persist();}P.closeModal();go('/orders');P.toast('演示售后申请已提交');}
 if(id==='notify-form'){P.openModal('订阅结果',`<div class="success"><div class="success-icon">${icon('check')}</div><h3>演示订阅成功</h3><p>此操作不会发送真实通知。</p><button class="primary-button" data-action="close">完成</button></div>`);}
 if(id==='shortcuts-form'){state.shortcuts=new FormData(form).getAll('shortcut');persist();applyShortcuts();P.closeModal();P.toast('快捷入口已保存');}
